import * as THREE from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/webgpu';
import { texture, color } from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const { scenePosition, sceneRotation, sceneScale } = config;

  // Load ceramic grain texture
  const textureMap = ctx.textureLoader.load('/prism-assets/chrome/ceramic-grain.map.png');
  textureMap.colorSpace = THREE.SRGBColorSpace;

  // Create TSL nodes for material
  const colorNode = texture(textureMap);
  const emissiveNode = color(new THREE.Color(0xff2a38)); // Accent red #ff2a38

  // Create material with accent edge light
  const material = new MeshBasicNodeMaterial();
  material.colorNode = colorNode;
  material.emissiveNode = emissiveNode;
  material.emissiveIntensity = 0.3;

  // Create plane geometry for capsule badge
  const geometry = new THREE.PlaneGeometry(0.8, 0.35);
  const mesh = new THREE.Mesh(geometry, material);

  // Apply scene transforms
  mesh.position.set(...scenePosition);
  mesh.rotation.set(...sceneRotation);
  mesh.scale.set(...sceneScale);

  // Store initial position for hover animation
  const initialPos = mesh.position.clone();
  let hoverTimeline, clickTimeline;

  // Store event metadata for framework
  mesh.userData.event = 'hub-pricing.select';

  // Setup interaction handlers
  mesh.userData.handlers = {
    onHover: (isHovering) => {
      if (hoverTimeline) hoverTimeline.kill();
      const targetY = isHovering ? initialPos.y + 0.15 : initialPos.y;
      hoverTimeline = gsap.to(mesh.position, {
        y: targetY,
        duration: 0.7,
        ease: 'power3.out'
      });
    },
    onClick: () => {
      if (clickTimeline) clickTimeline.kill();
      clickTimeline = gsap.to(mesh.scale, {
        x: 0.97,
        y: 0.97,
        duration: 0.12,
        ease: 'back.out',
        yoyo: true,
        repeat: 1
      });
    }
  };

  // Cleanup function to dispose resources
  mesh.userData.cleanup = () => {
    if (hoverTimeline) hoverTimeline.kill();
    if (clickTimeline) clickTimeline.kill();
    geometry.dispose();
    textureMap.dispose();
    material.dispose();
  };

  return mesh;
}
